from __future__ import annotations

from pathlib import Path

from compost.qmd import qmd_get as _qmd_get, qmd_query as _qmd_query


_SCOPE_TO_COLLECTION = {
    "team": "wiki",
    "raw": "raw",
    "decisions": "decisions",
    "incidents": "incidents",
}


def load_service_context(service: str, index: str, repo: Path) -> str:
    """Return formatted context for the named service."""
    parts: list[str] = [f"# Context for service: {service}\n"]

    # Try the canonical path first to avoid semantic search returning wrong service.
    canonical_uri = f"wiki/services/{service}.md"
    full = _qmd_get(canonical_uri, index)
    if full:
        parts.append(f"## Service page ({canonical_uri})\n\n{full}\n")
    else:
        hits = _qmd_query(f"service {service}", index, "wiki", limit=3)
        if not hits:
            return f"No wiki content found for service '{service}'."
        top = hits[0]
        full = _qmd_get(top["file"], index)
        parts.append(f"## Service page ({top['file']})\n\n{full}\n")

    dec_hits = _qmd_query(service, index, "decisions", limit=3)
    if dec_hits:
        parts.append("## Related decisions\n")
        for h in dec_hits:
            parts.append(f"- {h['file']}: {h.get('snippet', '')}\n")

    inc_hits = _qmd_query(service, index, "incidents", limit=3)
    if inc_hits:
        parts.append("\n## Related incidents\n")
        for h in inc_hits:
            parts.append(f"- {h['file']}: {h.get('snippet', '')}\n")

    return "".join(parts)


def query_wiki(query: str, index: str, scope: str = "team", limit: int = 5) -> str:
    """Return formatted search results."""
    collection = _SCOPE_TO_COLLECTION.get(scope, "wiki")
    hits = _qmd_query(query, index, collection, limit=limit)
    if not hits:
        return f"No results for query '{query}' in scope '{scope}'."

    lines = [f"# Results for: {query}\n"]
    for i, h in enumerate(hits, 1):
        score = h.get("score", "")
        snippet = h.get("snippet", "").strip()
        title = h.get("title", h["file"])
        lines.append(f"{i}. **{title}** ({h['file']}) score: {score}\n   {snippet}\n")
    return "\n".join(lines)

from __future__ import annotations

from pathlib import Path
from typing import Literal, TypedDict

import frontmatter as fm_lib

FrontmatterType = Literal[
    "service", "module", "decision", "runbook", "concept",
    "customer", "person", "project", "research",
]

REQUIRED_FIELDS = ("type", "name", "owners", "status", "updated",
                   "confidence", "sources")


class Frontmatter(TypedDict, total=False):
    type: FrontmatterType
    name: str
    owners: list[str]
    status: Literal["active", "deprecated", "archived"]
    updated: str
    confidence: Literal["high", "medium", "low"]
    sources: list[str]
    related: list[str]
    supersedes: list[str]
    superseded_by: str | None


def parse_frontmatter(path: Path) -> tuple[dict, str]:
    """Return (frontmatter_dict, body_text). Never raises; returns empty dict on parse failure."""
    try:
        post = fm_lib.load(str(path))
        return dict(post.metadata), post.content
    except Exception:
        return {}, path.read_text()


def validate_frontmatter(fm: dict, rel_path: Path) -> list[str]:
    """Return a list of human-readable error strings. Empty list means valid."""
    errors: list[str] = []
    prefix = str(rel_path)

    for field in REQUIRED_FIELDS:
        if field not in fm:
            errors.append(f"{prefix}: missing required field '{field}'")

    if "sources" in fm:
        if not fm["sources"]:
            errors.append(f"{prefix}: 'sources' must be non-empty")

    if "owners" in fm:
        if not fm["owners"]:
            errors.append(f"{prefix}: 'owners' must be non-empty")

    if "type" in fm:
        valid_types = {
            "service", "module", "decision", "runbook", "concept",
            "customer", "person", "project", "research",
        }
        if fm["type"] not in valid_types:
            errors.append(f"{prefix}: unknown type '{fm['type']}'")

    if "confidence" in fm:
        if fm["confidence"] not in ("high", "medium", "low"):
            errors.append(f"{prefix}: confidence must be high|medium|low")

    if "status" in fm:
        if fm["status"] not in ("active", "deprecated", "archived"):
            errors.append(f"{prefix}: status must be active|deprecated|archived")

    return errors

from pathlib import Path
import yaml


def find_repo_root(start: Path) -> Path | None:
    for parent in [start, *start.parents]:
        if (parent / ".compost.yml").exists():
            return parent
    return None


def load_repo_config(repo: Path) -> dict:
    config_file = repo / ".compost.yml"
    with config_file.open() as f:
        return yaml.safe_load(f)

from __future__ import annotations

import json
import subprocess


def qmd_query(query: str, index: str, collection: str, limit: int = 5) -> list[dict]:
    """BM25+vec search; returns hit dicts with keys: file, snippet, score, title."""
    result = subprocess.run(
        [
            "qmd", "--index", index,
            "query", query,
            "--collection", collection,
            "-n", str(limit),
            "--json",
            "--no-rerank",
        ],
        capture_output=True, text=True,
    )
    if result.returncode != 0:
        return []
    try:
        return json.loads(result.stdout)
    except json.JSONDecodeError:
        return []


def qmd_get(file_uri: str, index: str) -> str:
    """Return full document text for a qmd:// URI or relative path."""
    result = subprocess.run(
        ["qmd", "--index", index, "get", file_uri, "--full"],
        capture_output=True, text=True,
    )
    return result.stdout if result.returncode == 0 else ""

